"ITEMS_CRAFTED_5","BOSS_SLAIN_4","ALL_RARE_ENEMIES","DEATH_FROM_GRIM_TRAP","VICTORY","BOSS_CHALLENGE_1","BOSS_CHALLENGE_2","RESEARCHER_3","GAMES_PLAYED_3","HIGH_SCORE_3","MANY_BUFFS","ITEM_LEVEL_5","LEVEL_REACHED_5","HAPPY_END","VICTORY_RANDOM","HAPPY_END_REMAINS","RODNEY","VICTORY_WARRIOR","VICTORY_MAGE","VICTORY_ROGUE","VICTORY_HUNTRESS","VICTORY_DUELIST","VICTORY_CLERIC","VICTORY_ALL_CLASSES","DEATH_FROM_ALL","BOSS_SLAIN_3_GLADIATOR","BOSS_SLAIN_3_BERSERKER","BOSS_SLAIN_3_WARLOCK","BOSS_SLAIN_3_BATTLEMAGE",
